import csv,json,statistics as st
rows={'reference.csv':[],'candidates.csv':[]}
for name in rows:
    with open(name) as f:
        for r in csv.DictReader(f): rows[name].append(r)
ref=rows['reference.csv']; cand=rows['candidates.csv']
rs=st.median([float(r['score']) for r in ref]); cs=st.median([float(r['score']) for r in cand])
rq=st.median([float(r['qed']) for r in ref]); cq=st.median([float(r['qed']) for r in cand])
out={'reference_score_median':rs,'candidate_score_median':cs,'reference_qed_median':rq,'candidate_qed_median':cq,'score_condition':cs<rs,'qed_condition':cq>=rq}
out['verdict']='confirmed' if (out['score_condition'] and out['qed_condition']) else 'refuted'
print(json.dumps(out))
